"""Export Organ/Saw primary PCM and generate their checked region descriptors."""
from pathlib import Path
import wave
from parse_default_template import parse_asset
from export_template_wav import pcm_for_section

root = Path(__file__).resolve().parent.parent
data = (root / 'orgx/app/src/main/assets/Default.Template').read_bytes()
parsed = parse_asset(data, 'assets/Default.Template')
raw = root / 'orgx/app/src/main/res/raw'
lines = ['package com.hovait.orgx', '',
         '// Generated by analysis/export_orgx_regions.py from Default.Template.',
         'data class ReferenceRegion(val root:Int,val resource:Int,val loopStart:Int,val loopEnd:Int,val gain:Double)',
         'object ReferenceInstrumentRegions {']
for index, key in [(8, 'organ'), (7, 'lead')]:
    sections = parsed['instruments'][index]['sounds'][0]['sections']
    lines.append(f'    val {key}=listOf(')
    for section in sections:
        assert section['loop'] == 2
        name = f'orgx_{key}_zone_{section["note"]}'
        pcm = pcm_for_section(data, parsed, section)
        with wave.open(str(raw / f'{name}.wav'), 'wb') as output:
            output.setnchannels(section['channels'])
            output.setsampwidth(2)
            output.setframerate(section['sample_rate'])
            output.writeframes(pcm)
        gain=parsed['instruments'][index]['volume']*section['volume']/10000
        lines.append(f'        ReferenceRegion({section["note"]},R.raw.{name},{section["loop_start"]},{section["loop_end"]},{gain}),')
    lines.append('    )')
    print(key, len(sections), 'regions exported')
lines.append('}')
(root / 'orgx/app/src/main/java/com/hovait/orgx/ReferenceInstrumentRegions.kt').write_text('\n'.join(lines)+'\n',encoding='utf-8')
